  row.max_output_tokens === MAX_OUTPUT_TOKENS_SETTING &&
  Array.isArray(row.disallowedTools) &&
  row.disallowedTools.length === PINNED_DISALLOWED_TOOLS.length &&
  row.disallowedTools.every((t, i) => t === PINNED_DISALLOWED_TOOLS[i])
